def maximum_top(nums: list[int], k: int) -> int:
    n = len(nums)
    if k == 0:
        return nums[0]
    if n == 1:
        return -1 if k % 2 == 1 else nums[0]  # the pile alternates empty / full
    best = -1
    if k > 1:
        best = max(nums[:min(k - 1, n)])      # remove k-1, put the best one back
    if k < n:
        best = max(best, nums[k])             # remove exactly k, expose nums[k]
    return best

def min_operations(nums1: list[int], nums2: list[int]) -> int:
    s1, s2 = sum(nums1), sum(nums2)
    if s1 == s2:
        return 0
    if s1 > s2:
        nums1, nums2, s1, s2 = nums2, nums1, s2, s1  # nums1 now has the smaller sum
    gains = [0] * 6  # gains[g] = elements that can close the gap by up to g
    for x in nums1:
        gains[6 - x] += 1
    for y in nums2:
        gains[y - 1] += 1
    gap = s2 - s1
    ops = 0
    for g in range(5, 0, -1):
        if gap <= 0:
            break
        use = min(gains[g], (gap + g - 1) // g)
        ops += use
        gap -= use * g
    return ops if gap <= 0 else -1

def cycle_length_queries(n: int, queries: list[list[int]]) -> list[int]:
    answer = []
    for a, b in queries:
        da, db = a.bit_length(), b.bit_length()  # depth of each node
        if da > db:
            a >>= da - db
        else:
            b >>= db - da
        climb = (a ^ b).bit_length()  # edges from each side to the common ancestor
        answer.append(abs(da - db) + 2 * climb + 1)
    return answer

