def abbreviate_product(left: int, right: int) -> str:
    LIMIT = 10**10
    twos = fives = 0
    suffix = 1        # 2 and 5 free product modulo 10^5
    exact = 1         # 2 and 5 free product, kept exactly while small
    exact_ok = True
    leading = 1.0     # leading digits of the full product
    for x in range(left, right + 1):
        leading *= x
        while leading >= 1e12:
            leading /= 10
        while x % 2 == 0:
            x //= 2
            twos += 1
        while x % 5 == 0:
            x //= 5
            fives += 1
        suffix = suffix * x % 100000
        if exact_ok:
            exact *= x
            if exact >= LIMIT:
                exact_ok = False
    zeros = min(twos, fives)
    extra_twos, extra_fives = twos - zeros, fives - zeros
    # multiply the unmatched factors back into the suffix
    suffix = suffix * pow(2, extra_twos, 100000) * pow(5, extra_fives, 100000) % 100000
    if exact_ok:
        for factor, times in ((2, extra_twos), (5, extra_fives)):
            for _ in range(times):
                exact *= factor
                if exact >= LIMIT:
                    exact_ok = False
                    break
            if not exact_ok:
                break
    if exact_ok:
        return f"{exact}e{zeros}"
    while leading >= 100000:
        leading /= 10
    return f"{int(leading)}...{suffix:05d}e{zeros}"

def count_submatrices(grid: list[list[int]], k: int) -> int:
    n = len(grid[0])
    col = [0] * n  # col[j] = sum of column j over the rows seen so far
    count = 0
    for row in grid:
        running = 0  # prefix rectangle sum ending at the current cell
        for j in range(n):
            col[j] += row[j]
            running += col[j]
            if running <= k:
                count += 1
    return count

def assign_elements(groups: list[int], elements: list[int]) -> list[int]:
    limit = max(groups)
    best = [-1] * (limit + 1)  # best[s] = smallest index whose value divides s
    for j, e in enumerate(elements):
        if e > limit or best[e] != -1:
            continue  # too big, a repeat, or already covered by an earlier divisor
        for multiple in range(e, limit + 1, e):
            if best[multiple] == -1:
                best[multiple] = j
    return [best[g] for g in groups]

def minimum_string(a: str, b: str, c: str) -> str:
    def merge(s: str, t: str) -> str:
        if t in s:
            return s  # t is already covered
        for overlap in range(min(len(s), len(t)), 0, -1):
            if s.endswith(t[:overlap]):
                return s + t[overlap:]
        return s + t

    best = None
    for x, y, z in itertools.permutations((a, b, c)):
        candidate = merge(merge(x, y), z)
        if best is None or (len(candidate), candidate) < (len(best), best):
            best = candidate
    return best

