def before_and_after_puzzles(phrases: list[str]) -> list[str]:
    by_first = defaultdict(list)  # first word -> indices of phrases starting with it
    for idx, phrase in enumerate(phrases):
        by_first[phrase.split(" ", 1)[0]].append(idx)
    results = set()
    for i, phrase in enumerate(phrases):
        last = phrase.rsplit(" ", 1)[-1]
        for j in by_first.get(last, []):
            if j != i:
                results.add(phrase + phrases[j][len(last):])  # shared word once
    return sorted(results)

def smallest_number(num: int) -> int:
    if num == 0:
        return 0
    if num < 0:
        digits = sorted(str(-num), reverse=True)  # biggest magnitude
        return -int("".join(digits))
    digits = sorted(str(num))
    first = next(i for i, d in enumerate(digits) if d != "0")
    digits[0], digits[first] = digits[first], digits[0]  # no leading zero
    return int("".join(digits))

def camel_match(queries: list[str], pattern: str) -> list[bool]:
    def matches(query: str) -> bool:
        j = 0  # next pattern character to match
        for ch in query:
            if j < len(pattern) and ch == pattern[j]:
                j += 1
            elif ch.isupper():
                return False  # uppercase letters cannot be inserted
        return j == len(pattern)

    return [matches(q) for q in queries]

def max_vacation_days(flights: list[list[int]], days: list[list[int]]) -> int:
    n, k = len(days), len(days[0])
    # sources[c] = cities from which you can be in c next week (including c)
    sources = [[p for p in range(n) if p == c or flights[p][c]] for c in range(n)]
    best = [-1] * n  # -1 marks a city you cannot be in
    best[0] = 0      # before week 0 you are in city 0
    for w in range(k):
        new = [-1] * n
        for c in range(n):
            reach = max(best[p] for p in sources[c])
            if reach >= 0:
                new[c] = reach + days[c][w]
        best = new
    return max(best)

def people_indexes(favoriteCompanies: list[list[str]]) -> list[int]:
    ids = {}
    masks = []
    for companies in favoriteCompanies:
        mask = 0
        for name in companies:
            if name not in ids:
                ids[name] = len(ids)
            mask |= 1 << ids[name]
        masks.append(mask)
    result = []
    for i, mi in enumerate(masks):
        # i is dominated if some other mask contains all of its bits
        if not any(j != i and mi & mj == mi for j, mj in enumerate(masks)):
            result.append(i)
    return result

def smallest_subsequence(s: str, k: int, letter: str, repetition: int) -> str:
    n = len(s)
    remaining = s.count(letter)  # copies of letter at the current index or later
    stack = []
    in_stack = 0                 # copies of letter currently in the stack
    for i, c in enumerate(s):
        # pop larger characters while the length and letter targets stay reachable
        while (stack and stack[-1] > c and len(stack) - 1 + (n - i) >= k
               and (stack[-1] != letter or in_stack - 1 + remaining >= repetition)):
            if stack.pop() == letter:
                in_stack -= 1
        if len(stack) < k:
            if c == letter:
                stack.append(c)
                in_stack += 1
            elif k - len(stack) > repetition - in_stack:
                stack.append(c)  # a free slot not needed for the letter
        if c == letter:
            remaining -= 1
    return "".join(stack)

def equalize_water(buckets: list[int], loss: int) -> float:
    water = sorted(buckets)
    n = len(water)
    prefix = [0]
    for w in water:
        prefix.append(prefix[-1] + w)
    keep = (100 - loss) / 100

    def feasible(level: float) -> bool:
        below = bisect.bisect_left(water, level)  # buckets under the level
        deficit = level * below - prefix[below]
        surplus = (prefix[n] - prefix[below]) - level * (n - below)
        return surplus * keep >= deficit

    lo, hi = float(water[0]), float(water[-1])
    for _ in range(100):
        mid = (lo + hi) / 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    return lo

