    if len(nums) % 2 == 1:
        # one element survives; it can be any of them
        return total - min(nums)
    # two adjacent elements survive
    smallest_pair = min(nums[i] + nums[i + 1] for i in range(len(nums) - 1))
    return total - smallest_pair

