class DistanceLimitedPathsExist:
    def __init__(self, n: int, edgeList: list[list[int]]):
        self.parent = list(range(n))
        self.size = [1] * n
        self.when = [0] * n          # length of the edge that linked a node under its parent
        for u, v, dis in sorted(edgeList, key=lambda e: e[2]):
            ru, rv = self._root(u), self._root(v)
            if ru == rv:
                continue
            if self.size[ru] < self.size[rv]:
                ru, rv = rv, ru
            self.parent[rv] = ru     # no path compression: history stays intact
            self.when[rv] = dis
            self.size[ru] += self.size[rv]

    def _root(self, x: int) -> int:
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def _climb(self, x: int, limit: int) -> int:
        # follow only links created by edges shorter than limit
        while self.parent[x] != x and self.when[x] < limit:
            x = self.parent[x]
        return x

    def query(self, p: int, q: int, limit: int) -> bool:
        return self._climb(p, limit) == self._climb(q, limit)

