def longest_subsequence(nums: list[int]) -> int:
    V = max(nums)
    # best[v][d]: longest valid subsequence ending in value v whose last gap is >= d (0 = none yet)
    best = [None] * (V + 1)
    for x in nums:
        ending = [1] * (V + 1)            # ending[d]: last gap exactly d (or a lone element)
        for d in range(V + 1):
            top = 0
            lo, hi = x - d, x + d
            if lo >= 1 and best[lo] is not None:
                top = best[lo][d]
            if hi <= V and best[hi] is not None and best[hi][d] > top:
                top = best[hi][d]
            if top:
                ending[d] = top + 1
        # convert to "last gap at least d" with a suffix maximum
        for d in range(V - 1, -1, -1):
            if ending[d + 1] > ending[d]:
                ending[d] = ending[d + 1]
        row = best[x]
        best[x] = ending if row is None else [a if a > b else b for a, b in zip(row, ending)]
    return max(row[0] for row in best if row is not None)

