def count_operations_to_empty_array(nums: list[int]) -> int:
    n = len(nums)
    order = sorted(range(n), key=lambda i: nums[i])   # positions in deletion order
    ops = n                                          # every element is deleted once
    for i in range(1, n):
        if order[i] < order[i - 1]:
            # the pointer wraps around, passing all n - i remaining elements
            ops += n - i
    return ops

