def reconstruct_matrix(upper: int, lower: int, colsum: list[int]) -> list[list[int]]:
    twos = colsum.count(2)
    up, low = upper - twos, lower - twos      # quotas left for the 1 columns
    if up < 0 or low < 0:
        return []
    top, bottom = [], []
    for c in colsum:
        if c == 2:
            top.append(1); bottom.append(1)
        elif c == 0:
            top.append(0); bottom.append(0)
        elif up > 0:
            top.append(1); bottom.append(0); up -= 1
        else:
            top.append(0); bottom.append(1); low -= 1
    if up != 0 or low != 0:
        return []
    return [top, bottom]

def max_points_inside_square(points: list[list[int]], s: str) -> int:
    INF = float("inf")
    first = {}                     # tag -> smallest distance
    bound = INF                    # smallest "second closest" distance over all tags
    dist = []
    for (x, y), tag in zip(points, s):
        d = max(abs(x), abs(y))
        dist.append(d)
        if tag not in first:
            first[tag] = d
        elif d < first[tag]:
            bound = min(bound, first[tag])
            first[tag] = d
        else:
            bound = min(bound, d)
    return sum(1 for d in dist if d < bound)

