def valid_subarrays(nums: list[int]) -> int:
    n = len(nums)
    stack = []                 # indices with non decreasing values
    total = 0
    for j, value in enumerate(nums):
        while stack and nums[stack[-1]] > value:
            i = stack.pop()
            total += j - i     # subarrays starting at i end before j
        stack.append(j)
    for i in stack:
        total += n - i         # no smaller element to the right
    return total

