def min_cost(nums: list[int], k: int) -> int:
    n = len(nums)
    INF = float("inf")
    dp = [INF] * (n + 1)      # dp[i] = cheapest way to cut nums[i:]
    dp[n] = 0
    for i in range(n - 1, -1, -1):
        count = {}
        trimmed = 0           # trimmed length of nums[i..j]
        best = INF
        for j in range(i, n):
            v = nums[j]
            c = count.get(v, 0) + 1
            count[v] = c
            if c == 2:
                trimmed += 2  # both copies of v now stay in the piece
            elif c > 2:
                trimmed += 1
            cand = k + trimmed + dp[j + 1]
            if cand < best:
                best = cand
        dp[i] = best
    return dp[0]

def count_pairs(nums: list[int]) -> int:
    def almost_equal(a: str, b: str) -> bool:
        width = max(len(a), len(b))
        a = a.zfill(width)
        b = b.zfill(width)
        diff = [i for i in range(width) if a[i] != b[i]]
        if not diff:
            return True
        if len(diff) != 2:
            return False
        i, j = diff
        return a[i] == b[j] and a[j] == b[i]

    strs = [str(v) for v in nums]
    total = 0
    for i in range(len(strs)):
        for j in range(i + 1, len(strs)):
            if almost_equal(strs[i], strs[j]):
                total += 1
    return total
